@JsonPropertyOrder(alphabetic=true)
@JsonFormat(shape=JsonFormat.Shape.ARRAY)
static class PairBean {
    public String bar;
    public String foo;
    PairBean(String bar, String foo) { this.bar = bar; this.foo = foo; }
}

